WITH fn AS (SELECT p.oid,p.proacl,p.proowner,p.prosecdef,pg_get_functiondef(p.oid) AS definition FROM pg_proc p WHERE p.oid=to_regprocedure('public.inventory_soft_delete_manual_transactions(uuid[])')), problems AS (SELECT 'function_missing'::text AS audit_issue,'Thieu ham inventory_soft_delete_manual_transactions(uuid[])'::text AS detail WHERE NOT EXISTS(SELECT 1 FROM fn) UNION ALL SELECT 'security_definer_missing','Ham khong con SECURITY DEFINER' WHERE EXISTS(SELECT 1 FROM fn WHERE NOT prosecdef) UNION ALL SELECT 'safe_search_path_missing','Ham khong khoa search_path an toan' WHERE EXISTS(SELECT 1 FROM fn WHERE definition NOT ILIKE '%SET search_path TO %public%pg_temp%') UNION ALL SELECT 'product_lock_missing','Ham khong khoa theo tong ma hang' WHERE EXISTS(SELECT 1 FROM fn WHERE definition NOT ILIKE '%inventory_lock_product%') UNION ALL SELECT 'product_negative_guard_missing','Ham khong hau kiem am theo tong ma hang' WHERE EXISTS(SELECT 1 FROM fn WHERE definition NOT ILIKE '%inventory_assert_no_negative_product_after%') UNION ALL SELECT 'legacy_core_still_called','Ham public van goi legacy core' WHERE EXISTS(SELECT 1 FROM fn WHERE definition ILIKE '%inventory_soft_delete_manual_transactions_core_20260722%') UNION ALL SELECT 'legacy_customer_guard_still_called','Ham public van goi hang rao cu theo ma + khach' WHERE EXISTS(SELECT 1 FROM fn WHERE definition ~* 'inventory_assert_no_negative_after\s*\(') UNION ALL SELECT 'actor_date_guard_missing','Ham khong tu kiem tra quyen theo ngay giao dich' WHERE EXISTS(SELECT 1 FROM fn WHERE definition NOT ILIKE '%inventory_actor_can_change_transaction%') UNION ALL SELECT 'shipment_guard_missing','Ham khong chan giao dich chuyen hang' WHERE EXISTS(SELECT 1 FROM fn WHERE definition NOT ILIKE '%shipment_id IS NOT NULL%') UNION ALL SELECT 'delivery_plan_guard_missing','Ham khong chan giao dich ke hoach giao hang' WHERE EXISTS(SELECT 1 FROM fn WHERE definition NOT ILIKE '%delivery_plan_id IS NOT NULL%') UNION ALL SELECT 'stocktake_guard_missing','Ham khong chan giao dich phieu kiem ke' WHERE EXISTS(SELECT 1 FROM fn WHERE definition NOT ILIKE '%stocktake_id IS NOT NULL%') UNION ALL SELECT 'duplicate_guard_missing','Ham khong chan danh sach ID trung' WHERE EXISTS(SELECT 1 FROM fn WHERE definition !~* 'count\s*\(\s*DISTINCT\s+x\.id\s*\)') UNION ALL SELECT 'batch_limit_missing','Ham khong gioi han moi lan 100 giao dich' WHERE EXISTS(SELECT 1 FROM fn WHERE definition !~* 'v_requested_count\s*>\s*100') UNION ALL SELECT 'atomic_batch_guard_missing','Ham khong bat/tat che do thay theo goi' WHERE EXISTS(SELECT 1 FROM fn WHERE definition NOT ILIKE '%app.inventory_batch_replace%' OR definition NOT ILIKE '%EXCEPTION WHEN OTHERS%') UNION ALL SELECT 'adjustment_soft_cancel_missing','Ham khong huy mem dieu chinh lien quan' WHERE EXISTS(SELECT 1 FROM fn WHERE definition !~* 'adjusted_from_transaction_id\s*=\s*ANY\s*\(\s*p_transaction_ids\s*\)') UNION ALL SELECT 'base_count_guard_missing','Ham khong doi chieu du so dong goc da huy' WHERE EXISTS(SELECT 1 FROM fn WHERE definition !~* 'v_base_count\s*<>\s*v_requested_count') UNION ALL SELECT 'public_can_execute','PUBLIC van co quyen goi ham' WHERE EXISTS(SELECT 1 FROM fn CROSS JOIN LATERAL aclexplode(COALESCE(fn.proacl,acldefault('f',fn.proowner))) acl WHERE acl.grantee=0 AND acl.privilege_type='EXECUTE') UNION ALL SELECT 'anon_can_execute','anon van co quyen goi ham' WHERE to_regprocedure('public.inventory_soft_delete_manual_transactions(uuid[])') IS NOT NULL AND has_function_privilege('anon','public.inventory_soft_delete_manual_transactions(uuid[])','EXECUTE') UNION ALL SELECT 'authenticated_cannot_execute','authenticated khong goi duoc cong co hang rao' WHERE to_regprocedure('public.inventory_soft_delete_manual_transactions(uuid[])') IS NOT NULL AND NOT has_function_privilege('authenticated','public.inventory_soft_delete_manual_transactions(uuid[])','EXECUTE') UNION ALL SELECT 'legacy_core_exposed_to_authenticated','authenticated goi truc tiep duoc legacy core' WHERE to_regprocedure('public.inventory_soft_delete_manual_transactions_core_20260722(uuid[])') IS NOT NULL AND has_function_privilege('authenticated','public.inventory_soft_delete_manual_transactions_core_20260722(uuid[])','EXECUTE') UNION ALL SELECT 'legacy_core_exposed_to_anon','anon goi truc tiep duoc legacy core' WHERE to_regprocedure('public.inventory_soft_delete_manual_transactions_core_20260722(uuid[])') IS NOT NULL AND has_function_privilege('anon','public.inventory_soft_delete_manual_transactions_core_20260722(uuid[])','EXECUTE')), target AS (SELECT id,sku,name FROM public.products WHERE sku='YT2618 SP 0304' AND deleted_at IS NULL), checkpoint AS (SELECT ob.product_id,ob.period_month::date AS checkpoint_day,ob.opening_qty FROM public.inventory_opening_balances ob JOIN target p ON p.id=ob.product_id WHERE ob.deleted_at IS NULL AND ob.customer_id IS NULL AND ob.source_stocktake_id IS NOT NULL AND ob.period_month::date<='2026-07-27' ORDER BY ob.period_month DESC,ob.created_at DESC LIMIT 1), current_stock AS (SELECT p.id AS product_id,p.sku,p.name,c.checkpoint_day,c.opening_qty,c.opening_qty+COALESCE(sum(public.inventory_signed_effect(t.tx_type,t.qty,o.tx_type)),0) AS current_qty FROM target p JOIN checkpoint c ON c.product_id=p.id LEFT JOIN public.inventory_transactions t ON t.product_id=p.id AND t.deleted_at IS NULL AND t.tx_date::date>c.checkpoint_day AND t.tx_date::date<='2026-07-27' LEFT JOIN public.inventory_transactions o ON o.id=t.adjusted_from_transaction_id AND o.deleted_at IS NULL GROUP BY p.id,p.sku,p.name,c.checkpoint_day,c.opening_qty), output AS (SELECT 10 AS sort_order,'function_postfix_audit'::text AS section,jsonb_build_object('status',CASE WHEN EXISTS(SELECT 1 FROM problems) THEN 'STOP' ELSE 'OK' END,'problems',COALESCE((SELECT jsonb_agg(jsonb_build_object('issue',audit_issue,'detail',detail) ORDER BY audit_issue) FROM problems),'[]'::jsonb)) AS detail UNION ALL SELECT 20,'current_product_stock',COALESCE((SELECT to_jsonb(s) FROM current_stock s),'null'::jsonb) UNION ALL SELECT 30,'july_17_500_rows',COALESCE((SELECT jsonb_agg(jsonb_build_object('transaction_id',t.id,'tx_day',t.tx_date::date,'qty',t.qty,'note',t.note,'customer_id',t.customer_id,'created_at',t.created_at,'deleted_at',t.deleted_at) ORDER BY t.created_at,t.id) FROM public.inventory_transactions t JOIN target p ON p.id=t.product_id WHERE t.tx_date::date='2026-07-17' AND t.tx_type='in' AND t.qty=500),'[]'::jsonb)) SELECT section,detail FROM output ORDER BY sort_order;
